        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS serves Bakersfield and organizations throughout Kern County. Pickup planning can support business districts, industrial operations, schools, healthcare providers, and public agencies across the broader San Joaquin Valley service area."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Scheduling depends on volume, equipment type, loading access, and project requirements. Many organizations can arrange same-week pickup after discussing their inventory and collection needs with the STS team."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Available project records may include chain-of-custody documentation, asset lists, serialized reporting, and Certificates of Destruction. Documentation requirements should be discussed before pickup so the project can be scoped appropriately."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup really free?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is free for qualifying volumes. Eligibility depends on the quantity, type, and condition of equipment, along with collection logistics. Contact STS with an inventory summary to discuss whether your Bakersfield project qualifies."
          }
        },
        {
          "@type": "Question",
          "name": "What happens to my equipment after pickup?",
